def filter_dataframes(dataframes):
    filtered = {}
    for key, df in dataframes.items():
        if key == "sales_pipeline.csv":
            if "channel" in df.columns:
                filtered[key] = df[df["channel"].str.lower() != "partner"].copy()
            else:
                filtered[key] = df.copy()
        else:
            filtered[key] = df.copy()
    return filtered
